        let t12 = v[1] * v[1];
        let t13 = v[0].mul_add(v[0], t12);
        let t14 = xv[0] * t13;
        let t15 = t6 * t13;
            return Motor { c: gx::slots::from_values::<S, T, 4>([t14, t15, t8, t10]) };
